import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`agency-pitch-deck`,heroTitle:`Build your agency pitch deck in minutes`,heroSubtitle:`Perplexity Computer analyzes your agency's tone, services, and positioning, then builds a reusable pitch deck template — automatically.`,inputUrlCta:`Build my pitch deck`,inputUrlPlaceholder:`youragency.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of this agency — extract the brand voice, tone, visual style, color palette, service offerings, case studies, client types, unique selling propositions, and target verticals. Then build me a polished, reusable pitch deck template that I can personalize for every new client. The deck should include: 1) A compelling cover slide with agency name, tagline, and positioning. 2) An 'About Us' slide summarizing the agency's story, mission, and differentiators. 3) A 'Services' slide showcasing core offerings with clear descriptions. 4) A 'Case Studies / Results' slide template with placeholders for client name, challenge, solution, and outcomes. 5) A 'Why Us' slide with competitive advantages and proof points. 6) A 'Our Process' slide outlining how the agency works with clients. 7) A 'Pricing / Packages' slide template with placeholder tiers. 8) A 'Next Steps' slide with a clear CTA. Make the deck match the agency's brand voice and visual identity throughout. Include speaker notes for each slide with talking points. Export as a presentation I can edit and reuse.`,heroOverlaySteps:[`Analyzing your agency's brand voice, services, and positioning`,`Building a custom pitch deck template matched to your brand`,`Adding speaker notes, case study templates, and pricing frameworks`,`Your reusable pitch deck is complete — ready to personalize`],generatingSteps:[`Visiting {url} to extract brand voice, services, case studies, and visual identity`,`Designing an agent to structure a pitch deck matched to your agency's positioning`,`Configuring slide templates with speaker notes, proof points, and client placeholders`,`Setting up your reusable pitch deck for export and personalization`],featureSectionTitle:`From agency URL to client-ready pitch deck`,featureCardTitles:[`Connects to your agency stack`,`Outputs you can present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Slides, Google Drive, Notion, Canva, Slack — Computer builds your pitch deck and delivers it straight into the tools your team already uses.`,`Branded slide decks. Speaker notes for every slide. Case study templates. Pricing frameworks. A reusable deck you personalize for every prospect.`],capabilitySectionTitle:`Your pitch team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a client-ready pitch deck.`,capabilityCards:[{title:`Brand Extraction`,description:`Computer can analyze your agency website — voice, tone, services, case studies, and positioning — to build a complete brand profile for your deck.`},{title:`Deck Generation`,description:`Computer can structure a full pitch deck with cover, about, services, case studies, process, pricing, and next steps — all in your brand voice.`},{title:`Speaker Notes`,description:`Computer can write detailed talking points for every slide — so anyone on your team can deliver the pitch confidently.`},{title:`Connect Your Tools`,description:`Computer can push your deck to Google Drive, Notion, Canva, and Slack — build workflows across your entire agency stack.`},{title:`Remember & Refine`,description:`Computer can remember your agency profile, past decks, and winning pitches — so every new deck builds on what's worked before.`},{title:`Monitor & Update`,description:`Computer can watch your website for new services or case studies — and flag when your pitch deck template needs a refresh.`}]});export{t as default};
